// --- CONFIGURAÇÃO MESTRE: Yamar---
const body = $input.item.json.body || $input.item.json;
const telefoneRaw = body.telefone_cliente || body.telefone_contato || body.telefone || '';
const telefoneLimpo = telefoneRaw.toString().replace(/\D/g, '');
const nomePaciente = body.nome_cliente || body.nome_contato || 'Paciente';
const insistiu = body.insistiu === true || body.insistiu === 'true';
const TIMEZONE = 'America/Sao_Paulo';
// ── Unidade única ──────────────────────────────────────
const unidadeChave = 'yamar';
// ── Configurações por unidade ──────────────────────────────────
const CONFIGS = {
  yamar: {
    subscriber_id:            '6091062965829632',
    business_id:              '6091062965829632',
    nome_unidade:             'Yamar',
    nome_empresa:             'Yamar',
    link_agenda:              '177299',
    duracao_servico:          45,
    capacidade_simultanea:    2,
    timezone:                 TIMEZONE,
    limite_dias_busca_normal: 10,
    profissional: { id: '6194702674165760', nome: 'Jaqueline Akemi Yamashita' },
    authorization: 'Basic ' + Buffer.from('yamar:513b819a-fa96-4c40-94da-0e2ff08a6511').toString('base64')
  },
};
const CONFIG = CONFIGS[unidadeChave];
// ── Parse de datas — aceita ISO completo e destrincha data + hora ──
const hoje       = DateTime.now().setZone(TIMEZONE);
const dataInicio = hoje.toFormat('yyyy-MM-dd');
const dataRaw = body.data_iso || body.data_inicio || body.data_agendada || '';
let dtP = null;
if (dataRaw) {
  dtP = DateTime.fromISO(dataRaw, { zone: TIMEZONE });
  if (!dtP.isValid) dtP = DateTime.fromFormat(dataRaw, 'yyyy-MM-dd HH:mm', { zone: TIMEZONE });
  if (!dtP.isValid) dtP = DateTime.fromFormat(dataRaw, 'dd/MM/yyyy HH:mm', { zone: TIMEZONE });
}
// hora embutida no ISO (ex: "2026-03-11T14:00:00")
const horaDoISO = (dtP && dtP.isValid && (dtP.hour > 0 || dtP.minute > 0))
  ? dtP.toFormat('HH:mm') : '';
// prioridade: horario_agendado > horario > hora do ISO
const horaFinal = (body.horario_agendado && body.horario_agendado.length >= 4)
  ? body.horario_agendado
  : (body.horario && body.horario.length >= 4)
  ? body.horario
  : horaDoISO;
const dataFinal = (dtP && dtP.isValid) ? dtP.toFormat('yyyy-MM-dd') : '';
const dataFim   = (dtP && dtP.isValid)
  ? dtP.plus({ days: 7 }).toFormat('yyyy-MM-dd')
  : hoje.plus({ days: 7 }).toFormat('yyyy-MM-dd');
return {
  json: {
    acao_fluxo:        body.action || body.acao_fluxo,
    nome_paciente:     nomePaciente,
    telefone_limpo:    telefoneLimpo,
    insistiu:          insistiu,
    data_nascimento:   body.data_nascimento || '',
    data_inicio:       dataInicio,
    data_agendada:     dataFinal,
    data_antiga:       body.data_antiga || body['data-antiga'] || '',
    data_fim:          dataFim,
    horario_agendado:  horaFinal,
    config_agenda: {
      subscriber_id:            CONFIG.subscriber_id,
      business_id:              CONFIG.business_id,
      nome_unidade:             CONFIG.nome_unidade,
      nome_empresa:             CONFIG.nome_empresa,
      link_agenda:              CONFIG.link_agenda,
      duracao_servico:          CONFIG.duracao_servico,
      capacidade_simultanea:    CONFIG.capacidade_simultanea,
      timezone:                 CONFIG.timezone,
      limite_dias_busca_normal: CONFIG.limite_dias_busca_normal,
      profissional:             CONFIG.profissional,
      authorization:            CONFIG.authorization
    }
  }
};

// =============================================================
// LÓGICA INTELIGENTE — Yamar (multi-day)
// Formato: [{ Date, Week, DayWeek, AvaliableTimes:[{from,to,professionalId}], jsonDate }]
// =============================================================

// ── 1. CONFIGURAÇÃO ───────────────────────────────────────────
const cfgNode = $('Configuracao Unidades').first().json;
const ca = cfgNode.config_agenda || {};

const TIMEZONE  = ca.timezone || 'America/Sao_Paulo';
const DUR_MIN   = ca.duracao_servico || 45;
const LIMITE_DIAS = ca.limite_dias_busca_normal || 7;

// Profissional da unidade (vem do config_agenda)
const PROF_ID   = String(ca.profissional?.id || '');
const PROF_NOME = ca.profissional?.nome || 'Profissional';

// ── 2. INPUT ──────────────────────────────────────────────────
const diasAPI = $input.all().map(i => i.json);

// ── 3. DADOS DO PEDIDO ────────────────────────────────────────
const insistiu = cfgNode.insistiu === true;
const hRaw = cfgNode.horario_agendado || '';
const dRaw = cfgNode.data_agendada || '';   // yyyy-MM-dd
const agora = DateTime.now().setZone(TIMEZONE);

let dtSolicitado = null;
if (dRaw && hRaw) {
  dtSolicitado = DateTime.fromFormat(`${dRaw} ${hRaw}`, 'yyyy-MM-dd HH:mm', { zone: TIMEZONE });
}

let diffDias = 0, bloqueado = false;
if (dtSolicitado?.isValid) {
  diffDias = dtSolicitado.startOf('day').diff(agora.startOf('day'), 'days').days;
  if (diffDias > LIMITE_DIAS && !insistiu) bloqueado = true;
}

// ── 4. HELPERS ────────────────────────────────────────────────
function horaParaMin(str) {
  if (!str) return -1;
  const p = str.split(':');
  return parseInt(p[0]) * 60 + parseInt(p[1] || '0');
}

function sugerirEspalhados(blocos, n = 3) {
  const porDia = {};
  for (const b of blocos) {
    if (!porDia[b.data]) porDia[b.data] = b;
  }
  const dias = Object.keys(porDia).sort();
  if (dias.length <= n) return dias.map(d => porDia[d]);
  const resultado = [];
  const passo = (dias.length - 1) / (n - 1);
  for (let i = 0; i < n; i++) resultado.push(porDia[dias[Math.round(i * passo)]]);
  return resultado;
}

// ── 5. PROCESSAR UM DIA ───────────────────────────────────────
// Cada slot de 45 min disponível da Dra. = bloco válido
function processarDia(dia) {
  const slots = (dia.AvaliableTimes || []).filter(s => s.isSelectable !== false);
  const blocos = [];
  for (const slot of slots) {
    if (String(slot.professionalId) !== PROF_ID) continue;
    blocos.push({
      data:        dia.jsonDate,
      semana:      dia.Week,
      minutos:     horaParaMin(slot.from),
      horario:     slot.from,
      horario_fim: slot.to,
      profId:      PROF_ID,
      profNome:    PROF_NOME
    });
  }
  return blocos.sort((a, b) => a.minutos - b.minutos);
}

// ── 6. TODOS OS BLOCOS ────────────────────────────────────────
let todosBlocos = [];
for (const dia of diasAPI) todosBlocos = todosBlocos.concat(processarDia(dia));

// ── 7. FORMATAÇÃO ─────────────────────────────────────────────
const fmtBloco = b => {
  const [yyyy, mm, dd] = b.data.split('-');
  return `🗓️ *${dd}/${mm} (${b.semana})* às *${b.horario}* – *${b.horario_fim}* com ${b.profNome}`;
};

const dtLabel = dtSolicitado?.isValid
  ? dtSolicitado.setLocale('pt-BR').toFormat('dd/MM (cccc)')
  : (dRaw || 'data solicitada');

// ── 8. DECISÃO PRINCIPAL ──────────────────────────────────────
let resultado, exactMatch = false;
const sugestoesHorarios = [];

// CAMINHO A — Data distante + NÃO insistiu
if (bloqueado) {
  const limiteData = agora.startOf('day').plus({ days: LIMITE_DIAS }).toFormat('yyyy-MM-dd');
  const proximos = sugerirEspalhados(todosBlocos.filter(b => b.data <= limiteData), 3);
  if (proximos.length === 0) {
    resultado = `😕 Não há horários disponíveis nos próximos ${LIMITE_DIAS} dias.\n\nPosso verificar outra data?`;
  } else {
    proximos.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
    resultado =
      `⚠️ A data que você pediu (*${dtLabel}*) está a *${Math.ceil(diffDias)} dias* de hoje.\n\n` +
      `Para garantir um atendimento mais rápido, separei os horários disponíveis mais próximos:\n\n` +
      proximos.map(fmtBloco).join('\n');
  }
}

// CAMINHO B — Data distante + insistiu
else if (diffDias > LIMITE_DIAS && insistiu) {
  const dataAlvo = dtSolicitado.toFormat('yyyy-MM-dd');
  const minSolicitado = (hRaw && hRaw !== '00:00') ? horaParaMin(hRaw) : -1;
  const blocosDoDia = todosBlocos.filter(b => b.data === dataAlvo);
  const blocoExato = minSolicitado >= 0 ? blocosDoDia.find(b => b.minutos === minSolicitado) : null;

  if (blocoExato) {
    exactMatch = true;
    sugestoesHorarios.push(`${blocoExato.data} ${blocoExato.horario}`);
    resultado = `✅ Consegui o horário que você pediu!\n\n${fmtBloco(blocoExato)}\n\nConfirmo o agendamento?`;
  } else if (blocosDoDia.length === 0) {
    resultado = `😕 Não há horários disponíveis em *${dtLabel}*.\n\nPosso verificar um dia antes ou depois?`;
  } else {
    const opcoes = blocosDoDia.slice(0, 3);
    opcoes.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
    resultado =
      `O horário das *${hRaw}* não está disponível em *${dtLabel}*, mas encontrei estas opções neste mesmo dia:\n\n` +
      opcoes.map(fmtBloco).join('\n') + `\n\nQual prefere? Ou verifico outro dia?`;
  }
}

// CAMINHOS C / D — Data normal (≤ 7 dias)
else {
  const dataAlvo = dtSolicitado?.isValid ? dtSolicitado.toFormat('yyyy-MM-dd') : null;
  const minSolicitado = (hRaw && hRaw !== '00:00') ? horaParaMin(hRaw) : -1;
  const blocosDoDia = dataAlvo ? todosBlocos.filter(b => b.data === dataAlvo) : todosBlocos;
  const blocoExato = (minSolicitado >= 0 && blocosDoDia.length > 0)
    ? blocosDoDia.find(b => b.minutos === minSolicitado) : null;

  if (blocoExato) {
    exactMatch = true;
    sugestoesHorarios.push(`${blocoExato.data} ${blocoExato.horario}`);
    resultado =
      `✅ Ótima notícia! O horário *${dtLabel} às ${blocoExato.horario}* está disponível ` +
      `com *${blocoExato.profNome}*.\n\nPosso confirmar sua avaliação?`;
  } else if (blocosDoDia.length === 0) {
    const proximos = sugerirEspalhados(todosBlocos, 3);
    if (proximos.length === 0) {
      resultado = `😕 Não há horários disponíveis no período consultado. Posso verificar outras datas?`;
    } else {
      proximos.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
      resultado =
        `😕 Não há horários disponíveis em *${dtLabel}*.\n\nEncontrei estas opções nos próximos dias:\n\n` +
        proximos.map(fmtBloco).join('\n') + `\n\nQual desses fica melhor para você?`;
    }
  } else {
    const opcoes = blocosDoDia.slice(0, 3);
    opcoes.forEach(b => sugestoesHorarios.push(`${b.data} ${b.horario}`));
    const intro = minSolicitado >= 0
      ? `O horário das *${hRaw}* não está disponível para *${dtLabel}*, mas tenho estas opções:`
      : `Encontrei os seguintes horários disponíveis para *${dtLabel}*:`;
    resultado = `📅 ${intro}\n\n` + opcoes.map(fmtBloco).join('\n') + `\n\nQual desses fica melhor para você?`;
  }
}

// ── 9. OUTPUT ─────────────────────────────────────────────────
return {
  json: {
    resultado,
    sugestoes_horarios:      sugestoesHorarios,
    data_distante_bloqueada: bloqueado,
    exact_match:             exactMatch,
    diff_dias:               Math.ceil(diffDias),
    total_dias_api:          diasAPI.length,
    total_blocos_validos:    todosBlocos.length
  }
};

// ── Validar Slot Agendar —  ─────────────────────────
let d = {};
try { d = $('Configuracao Unidades').first().json; } catch(e) { d = $input.item.json; }

const PROF_ID   = String(d.config_agenda?.profissional?.id || '');
const PROF_NOME = d.config_agenda?.profissional?.nome || 'Profissional';

const inputItems    = $input.all().map(i => i.json);
const isNovoFormato = inputItems.length > 0 && Array.isArray(inputItems[0].AvaliableTimes);

let slots = [];
if (isNovoFormato) {
  slots = (inputItems[0].AvaliableTimes || []).filter(s => s.isSelectable !== false);
} else {
  slots = inputItems;
}

const norm = h => {
  if (!h) return '';
  const p = h.toString().split(':');
  return p[0].padStart(2,'0') + ':' + (p[1]||'00').padStart(2,'00');
};

const hAlvo = norm(d.horario_agendado || '');

function temSlot() {
  return slots.some(s => {
    const id   = String(isNovoFormato ? s.professionalId : s.ProfessionalId);
    const from = norm(isNovoFormato ? s.from : s.From);
    return id === PROF_ID && from === hAlvo;
  });
}

let v = { aprovado: false, motivo: 'Horário indisponível.' };
let idF = null, nomeF = '';

if (!slots.length) {
  v.motivo = 'Não há agenda aberta ou horários disponíveis neste dia.';
} else if (!hAlvo) {
  v.motivo = 'Horário solicitado não informado.';
} else if (temSlot()) {
  v = { aprovado: true, motivo: 'Horário disponível.' };
  idF = PROF_ID; nomeF = PROF_NOME;
} else {
  v.motivo = `O horário ${d.horario_agendado} não está disponível.`;
}

return {
  json: {
    ...d,
    validacao:               v,
    id_profissional_final:   idF,
    nome_profissional_final: nomeF,
    hora_buscada:            hAlvo,
    slots_encontrados_total: slots.length
  }
};

