// ── Recuperar Reagendamento — Yamar ──────────────────────
const base = $('Validar Slot Remarcar').first().json;
const dur  = base.config_agenda?.duracao_servico || 45;

// ISO da nova data+hora com fuso Brasil
const dataISO = DateTime.fromFormat(
  base.data_agendada + ' ' + base.horario_agendado,
  'yyyy-MM-dd HH:mm',
  { zone: 'America/Sao_Paulo' }
).toISO();

// toTime pré-calculado
const toTime = DateTime.fromFormat(base.horario_agendado, 'HH:mm')
  .plus({ minutes: dur })
  .toFormat('HH:mm');

return {
  json: {
    ...base,
    id_paciente_final: base.patient_id_remarcar,  // já vem do Validar Slot Remarcar
    data_agendada_iso: dataISO,
    toTime_calculado:  toTime
  }
};

const config   = $('Configuracao Unidades').first().json;
const horaAlvo = config.horario_agendado;
const agmts    = $input.all().map(i=>i.json);

const norm = h => {
  if(!h) return '';
  const p=h.toString().split(':');
  return p[0].padStart(2,'0')+':'+(p[1]||'00').padStart(2,'0');
};

let enc = null;
for(const a of agmts){
  if(a.Deleted!=='X' && norm(a.fromTime)===norm(horaAlvo)){ enc=a; break; }
}

return { json: { ...config, agendamento_id: enc?enc.id:null, agendamento_encontrado:!!enc, dados_agendamento:enc||null } };

const config = $('Configuracao Unidades').first().json;
const agmts  = $input.all().map(i => i.json);
let enc = null;
for (const a of agmts) {
  if (a.id && a.Deleted !== 'X') { enc = a; break; }  // ← adicionado: a.id
}
return { json: { ...config,
  agendamento_id_antigo:    enc ? enc.id : null,
  agendamento_encontrado:   !!enc,
  dados_agendamento_antigo: enc || null,
  data_hora_antiga:         enc ? (enc.AppointmentDate + ' ' + enc.fromTime) : null
} };

const config = $('Configuracao Unidades').first().json;
const agmts  = $input.all().map(i => i.json);
let prox = null;

for (const a of agmts) {
  if (a.id && a.Deleted !== 'X') { prox = a; break; }  // a.id evita falso positivo do alwaysOutputData
}

return { json: { ...config,
  proximo_encontrado: !!prox,
  proximo_data:       prox ? prox.AppointmentDate : null,
  proximo_hora:       prox ? prox.fromTime : null,
  proximo_id:         prox ? prox.id : null,
  dados_proximo:      prox || null
} };
